UPDATE sys_menu AS menu SET sort_order = ordering.sort_order, updated_at = CURRENT_TIMESTAMP, version = menu.version + 1 FROM (VALUES
(#{item.menuId}, #{item.sortOrder}, #{item.version})
) AS ordering(menu_id, sort_order, expected_version) WHERE menu.id = ordering.menu_id AND menu.version = ordering.expected_version AND menu.deleted = 0
